window.pfMonths = function (desde, hasta) {
  const L = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  const out = [];
  let [y, m] = (desde || '2025-01').split('-').map(Number);
  const [hy, hm] = (hasta || '2029-12').split('-').map(Number);
  while (y < hy || (y === hy && m <= hm)) {
    out.push({ id: y + '-' + String(m).padStart(2,'0'), y, m, label: L[m-1] + ' ' + String(y).slice(2), q: Math.ceil(m/3) });
    m++; if (m > 12) { m = 1; y++; }
  }
  return out;
};

// Un mes de cartera real, por segmento y agregado. Devuelve null donde no hay
// dato en vez de cero, que es lo que distingue "no hay cartera" de "no medido".
window.pfReal = function (mes) {
  const segs = window.PF_SEGS.map(s => {
    const r = window.PF_REAL[s.id] || {};
    const cli = (r.clientes || {})[mes];
    const out = (r.outstanding || {})[mes];
    const lin = (r.lineas || {})[mes];
    const hay = cli != null && lin != null && (cli > 0 || lin > 0);
    return { ...s, cli: hay ? cli : null, out: hay ? out : null, lineas: hay ? lin : null,
      util: hay && lin ? out / lin : null,
      // Línea media de la propia hoja: TICKET MEDIO LÍNEA, sobre clientes al
      // corriente. Dividir lineas/cli mezclaría el total de líneas de todos los
      // clientes con el recuento de los activos.
      linea: hay ? (r.ticketLinea || {})[mes] : null,
      // Y el total de líneas dividido por clientes activos se mantiene aparte,
      // con su nombre, porque es otra magnitud.
      lineaPorActivo: hay && cli ? lin / cli : null,
      ticketOut: hay && cli ? out / cli : null };
  });
  const cli = segs.reduce((a, s) => a + (s.cli || 0), 0);
  const out = segs.reduce((a, s) => a + (s.out || 0), 0);
  const lin = segs.reduce((a, s) => a + (s.lineas || 0), 0);
  // La línea media del conjunto es la ponderada por clientes de la de cada
  // segmento, no el total de líneas entre el total de clientes activos.
  const pond = segs.reduce((a, s) => a + ((s.linea || 0) * (s.cli || 0)), 0);
  return { mes, segs, cli, out, lineas: lin,
    util: lin ? out / lin : null,
    linea: cli ? pond / cli : null,
    lineaPorActivo: cli ? lin / cli : null };
};

// Un mes del BP, con las unidades ya normalizadas a euros.
window.pfBp = function (mes) {
  const segs = window.PF_SEGS.map(s => {
    const b = window.PF_BP[s.id] || {};
    const cli = (b.clientes || {})[mes];
    return { ...s, cli,
      loanbook: (b.loanbook || {})[mes] != null ? b.loanbook[mes] * 1e6 : null,
      lineas: (b.lineas || {})[mes] != null ? b.lineas[mes] * 1e6 : null,
      linea: (b.linea || {})[mes] != null ? b.linea[mes] * 1e3 : null,
      util: (b.util || {})[mes],
      nuevos: (b.nuevos || {})[mes], churn: (b.churn || {})[mes] };
  });
  const t = window.PF_BP.total || {};
  return { mes, segs,
    cli: (t.clientes || {})[mes],
    loanbook: (t.loanbook || {})[mes] != null ? t.loanbook[mes] * 1e6 : null,
    lineas: (t.lineas || {})[mes] != null ? t.lineas[mes] * 1e6 : null,
    linea: (t.linea || {})[mes] != null ? t.linea[mes] * 1e3 : null,
    util: (t.util || {})[mes] };
};

// Plan contra real en el último mes con las dos cifras: el contraste que dice
// si el BP va por delante o por detrás de la cartera.
window.pfGap = function (mes) {
  const m = mes || window.PF_META.realHasta;
  const r = window.pfReal(m), b = window.pfBp(m);
  const segs = window.PF_SEGS.map(s => {
    const rs = r.segs.find(x => x.id === s.id) || {};
    const bs = b.segs.find(x => x.id === s.id) || {};
    return { ...s, real: rs, bp: bs,
      cliGap: rs.cli != null && bs.cli != null ? rs.cli - bs.cli : null,
      cliPct: rs.cli != null && bs.cli ? rs.cli / bs.cli : null,
      lbGap: rs.out != null && bs.loanbook != null ? rs.out - bs.loanbook : null,
      lbPct: rs.out != null && bs.loanbook ? rs.out / bs.loanbook : null };
  });
  return { mes: m, real: r, bp: b, segs,
    cliPct: r.cli && b.cli ? r.cli / b.cli : null,
    lbPct: r.out && b.loanbook ? r.out / b.loanbook : null };
};

// ============= FORMATO =============
// Un solo agrupador y dos precisiones declaradas, para que la misma magnitud no
// se pinte con dos precisiones en dos pestañas.
window.pfFmt = {
  n: function (v) {
    if (v == null || isNaN(v)) return '—';
    const n = Math.round(v);
    return String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.').replace(/^/, n < 0 ? '-' : '');
  },
  // Cartera: un decimal en millones. 3,6M€ contra 4,1M€ deja ver el 89%.
  cartera: function (v) {
    if (v == null || isNaN(v)) return '—';
    if (v >= 1e6) return (v / 1e6).toFixed(1).replace('.', ',') + 'M€';
    if (v >= 1e3) return window.pfFmt.n(v / 1e3) + 'k€';
    return window.pfFmt.n(v) + '€';
  },
  // Plan: millones enteros. A 716M€ o 1.580M€ el decimal no informa.
  plan: function (v) {
    if (v == null || isNaN(v)) return '—';
    if (v >= 1e6) return window.pfFmt.n(v / 1e6) + 'M€';
    if (v >= 1e3) return window.pfFmt.n(v / 1e3) + 'k€';
    return window.pfFmt.n(v) + '€';
  },
  keur: function (v) { return v == null || isNaN(v) ? '—' : window.pfFmt.n(v / 1e3) + 'k€'; },
};
